group by (pod, reason) (
  kube_pod_container_status_last_terminated_reason{cluster=~"$cluster", namespace=~"$namespace",container=~"store-gateway",reason="OOMKilled"}
  unless
  # Note, this leg offsets by the "$__interval" to find the first occurrence of OOMKilled in the gauge.
  (kube_pod_container_status_last_terminated_reason{cluster=~"$cluster", namespace=~"$namespace",container=~"store-gateway",reason="OOMKilled"} offset $__interval == bool 0)
) != 0

sum by(instance, pod, device) (
  rate(
    node_disk_written_bytes_total[$__rate_interval]
  )
)
+
ignoring(pod) group_right() (
  label_replace(
    count by(
      instance,
      pod,
      device
    )
    (
      container_fs_writes_bytes_total{
        cluster=~"$cluster", namespace=~"$namespace",
        container=~"store-gateway",
        device!~".*sda.*"
      }
    ),
    "device",
    "$1",
    "device",
    "/dev/(.*)"
  ) * 0
)

sum by(instance, pod, device) (
  rate(
    node_disk_read_bytes_total[$__rate_interval]
  )
) + ignoring(pod) group_right() (
  label_replace(
    count by(
      instance,
      pod,
      device
    )
    (
      container_fs_writes_bytes_total{
        cluster=~"$cluster", namespace=~"$namespace",
        container=~"store-gateway",
        device!~".*sda.*"
      }
    ),
    "device",
    "$1",
    "device",
    "/dev/(.*)"
  ) * 0
)

group by (pod, reason) (
  kube_pod_container_status_last_terminated_reason{cluster=~"$cluster", namespace=~"$namespace",container=~"ruler",reason="OOMKilled"}
  unless
